typedef unsigned int u_int;

struct nglTexture;
struct nglQuad;

extern void nglSetQuadTex(nglQuad *, nglTexture *);
extern void nglSetQuadMapFlags(nglQuad *, u_int);

class PanelQuad
{
    char pad[0x1c];
    nglQuad *quad;
public:
    virtual nglTexture *GetTexture();
    void setTexture(nglTexture *texture) { nglSetQuadTex(quad, texture); }
    void setMaterialFlags(u_int flags) { nglSetQuadMapFlags(quad, flags); }
};

class PanelFile
{
public:
    void Reload();
};

class FEMultiMenu
{
    char pad0[0x64];
    void *manager;
    char pad1[0x98];
    PanelFile panel;
public:
    void ReloadPanel();
};

class BeachFrontEnd : public FEMultiMenu
{
    char pad0[0xd08];
    PanelQuad *line_across;
    char pad1[0x7c];
    PanelQuad *locked_light_template;
    PanelQuad *locked_first_light_template;
    PanelQuad *unlocked_light_template;
    char pad2[0x10];
    PanelQuad *completed_lights[3][5][2];
    char pad3[0x18];
    PanelQuad *chall_div_line;
public:
    void ReloadPanel();
};

enum
{
    NGLMAT_TEXTURE_MAP = 0x1000,
    NGLMAT_BILINEAR_FILTER = 0x10,
    NGLMAT_CLAMP_U = 0x10000,
    NGLMAT_CLAMP_V = 0x20000,
    NGLMAP_BILINEAR_FILTER = 0x2,
    NGLMAP_CLAMP_U = 0x10,
    NGLMAP_CLAMP_V = 0x20,
    MAX_BEACHES_PER_LOC = 3,
    MAX_GOALS_PER_LEVEL = 5
};

void BeachFrontEnd::ReloadPanel()
{
	FEMultiMenu::ReloadPanel();

	chall_div_line->setMaterialFlags(NGLMAT_CLAMP_U | NGLMAT_CLAMP_V | NGLMAT_TEXTURE_MAP | NGLMAT_BILINEAR_FILTER);
	chall_div_line->setTexture(line_across->GetTexture());
	for(int i=0; i<MAX_BEACHES_PER_LOC; i++)
		for(int j=0; j<MAX_GOALS_PER_LEVEL; j++)
		{
			completed_lights[i][j][0]->setMaterialFlags(NGLMAP_CLAMP_U | NGLMAP_CLAMP_V | NGLMAP_BILINEAR_FILTER);
			completed_lights[i][j][0]->setTexture(j == 0 ? locked_first_light_template->GetTexture() : locked_light_template->GetTexture());
			completed_lights[i][j][1]->setMaterialFlags(NGLMAP_CLAMP_U | NGLMAP_CLAMP_V | NGLMAP_BILINEAR_FILTER);
			completed_lights[i][j][1]->setTexture(unlocked_light_template->GetTexture());
		}
}
